    AND t.kind = #{q.kind}
    AND t.partner_id = #{q.partnerId}
    AND t.status = #{q.status}
    AND t.item = #{q.item}

        AND (t.offset_no LIKE CONCAT('%', #{q.keyword}, '%') OR t.ticket_no LIKE CONCAT('%', #{q.keyword}, '%'))

    AND t.offset_date >= #{q.beginDate}
    AND t.offset_date <= #{q.endDate}

